$$("[data-theme]").forEach(b=>b.onclick=()=>{db.settings.theme=b.dataset.theme;saveDB();applyTheme()});
$("#themeToggle").onclick=()=>{if(!requirePin("modifier le thème"))return;db.settings.theme=db.settings.theme==="dark"?"light":"dark";saveDB();applyTheme()};
$("#savePin").onclick=()=>{
  const entered=$("#oldPin").value;
  if(entered==="0509"){
    const n=prompt("Réinitialisation acceptée. Entrez le nouveau code de 4 à 8 chiffres :");
    if(n && /^\d{4,8}$/.test(n)){db.security.pin=n;db.security.lastUnlock=Date.now();saveDB();authenticated=true;$("#oldPin").value=$("#newPin").value=$("#confirmPin").value="";alert("Code de déverrouillage réinitialisé.");}
    else if(n!==null) alert("Code invalide.");
    return;
  }
  if(entered!==db.security.pin){alert("Code actuel incorrect.");return}
  const np=$("#newPin").value,cp=$("#confirmPin").value;
  if(!/^\d{4,8}$/.test(np)){alert("Le code doit contenir 4 à 8 chiffres.");return}
  if(np!==cp){alert("Les codes ne correspondent pas.");return}
  db.security.pin=np;db.security.lastUnlock=Date.now();saveDB();authenticated=true;
  $("#oldPin").value=$("#newPin").value=$("#confirmPin").value="";
  alert("Code de déverrouillage modifié.");
};
loadSettings();resetForm();renderDashboard();if((db.security.lockMode||"immediate")==="immediate")setTimeout(()=>requirePin("ouvrir l’application"),100);

if("serviceWorker" in navigator) navigator.serviceWorker.register("service-worker.js").catch(()=>{});
db.security.lockMode=db.security.lockMode||"immediate";db.security.lastUnlock=db.security.lastUnlock||0;

window.addEventListener("load",()=>{const e=document.querySelector("#pinLockMode");if(e)e.value=db.security.lockMode||"immediate";});
